const {chromium}=require('playwright-core');
const assert=require('node:assert/strict');
const path=require('node:path');
const base='http://localhost:8080';
(async()=>{
  const browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
  try{
    const page=await browser.newPage();const errors=[];
    page.on('pageerror',error=>errors.push(error.message));
    page.on('console',message=>{if(message.type()==='error')errors.push(message.text())});
    await page.route('**/api/auth/session',route=>route.fulfill({json:{user:{id:'synthetic',username:'u'.repeat(32),role:'user'},csrf_token:'synthetic-token'}}));
    await page.route('**/layout-thumbnail',route=>route.fulfill({contentType:'image/svg+xml',body:'<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180"><rect width="320" height="180" fill="#eee"/></svg>'}));
    await page.route('**/api/videos?*',route=>{
      const q=new URL(route.request().url()).searchParams.get('q');
      return route.fulfill({json:{items:[1,2,3].map(id=>({id:String(id),title:q==='short'?'Короткий результат '+id:'Видео '+id,channel:{id:'channel',title:'Канал',username:'author'},duration_ms:2000,published_at:'2026-11-15T00:00:00Z',thumbnail_url:'/layout-thumbnail',watch_url:'/watch/'+id})),next_cursor:null}});
    });
    for(const width of [1440,390]){
      await page.setViewportSize({width,height:1000});
      await page.goto(base+'/results?q='+'w'.repeat(200));
      await page.getByRole('button',{name:'Выйти',exact:true}).waitFor();
      await page.locator('.video-card').nth(2).waitFor();
      for(const query of ['w'.repeat(200),'short']){
        if(query==='short'){
          await page.getByRole('searchbox',{name:'Поиск видео'}).fill(query);
          await page.getByRole('button',{name:'Найти видео'}).click();
          await page.getByRole('heading',{name:'Короткий результат 1',exact:true}).waitFor();
        }
        assert.equal(await page.locator('.page-heading h1').innerText(),'Результаты: '+query);
        const measured=await page.evaluate(()=>{
          const rect=selector=>document.querySelector(selector).getBoundingClientRect();
          const overlaps=(a,b)=>a.left<b.right&&b.left<a.right&&a.top<b.bottom&&b.top<a.bottom;
          const heading=rect('.page-heading h1'),label=rect('.category-label'),main=rect('main'),sidebar=rect('.sidebar'),grid=rect('.video-grid'),account=rect('.account'),search=rect('.search-bar'),brand=rect('.brand'),header=rect('.topbar');
          const cards=[...document.querySelectorAll('.video-card')].map(node=>node.getBoundingClientRect());
          return {scrollWidth:document.documentElement.scrollWidth,width:innerWidth,contained:heading.left>=main.left&&heading.right<=main.right&&account.top>=header.top&&account.bottom<=header.bottom,noOverlaps:!overlaps(main,sidebar)&&!overlaps(brand,account)&&!overlaps(search,account)&&!(label.width&&overlaps(heading,label))&&heading.bottom<=grid.top&&cards.every((a,i)=>cards.every((b,j)=>i===j||!overlaps(a,b)))};
        });
        assert(measured.scrollWidth<=measured.width,JSON.stringify(measured));
        assert(measured.contained&&measured.noOverlaps,JSON.stringify(measured));
        if(process.env.ARTIFACT_DIR)await page.screenshot({path:path.join(process.env.ARTIFACT_DIR,`search-${query==='short'?'short':'long'}-${width}.png`),fullPage:true});
        console.log(`OK ${query==='short'?'short query':'200 w query'}, username 32, ${width}px: scrollWidth=${measured.scrollWidth}, no overlaps`);
      }
    }
    assert.deepEqual(errors,[]);console.log('OK no console errors or uncaught exceptions');
  }finally{await browser.close()}
})().catch(error=>{console.error(error.message);process.exitCode=1});
# Лента, поиск и взаимодействия: подготовка к четвёртому коммиту

Дата проверки: 15 ноября 2026 года. Изменения готовы к независимому ревью;
коммит и push не выполнялись. Требования: F02, F05, F06, F09 и относящиеся к ним
части F03/F13 и серверной защиты из [requirements.md](requirements.md).

## Состояние при возобновлении

В рабочем дереве уже находились API ленты/поиска, лайков и комментариев,
SQLAlchemy-модели, миграция, keyset cursor, страницы и браузерные тесты.
Реализация сохранена. Сохранились два скриншота главной и синтетический MP4;
самостоятельного итогового протокола прежних 147 тестов/E2E не обнаружено.

Работающий стенд отставал от файлов: backend ещё содержал условия публичной
выдачи непосредственно в feed, а frontend — прежний CSS. Контейнеры приложения
пересобраны/обновлены для проверки актуального дерева. PostgreSQL и SeaweedFS
не пересоздавались, volumes не удалялись.

## Дополнительные изменения

- Исправлена мобильная шапка: при username из 32 символов имя обрезалось сверху,
  а кнопка выхода перекрывала поиск. Блок аккаунта теперь оставляет кнопку
  рядом с переносимым именем. Регрессия включена в `tests/e2e/feed_state.cjs`.
- `tests/e2e/social.cjs` дополнен снимками главной, поиска и просмотра на обеих
  ширинах и контролем console errors/pageerror. Ожидаемый 401 от проверки
  отсутствующей гостевой сессии не считается ошибкой приложения.
- Добавлен этот протокол. Backend, миграция и бизнес-правила при завершении
  этапа не переписывались.

## Готовые интерфейсы и схема

| Интерфейс | Поведение |
| --- | --- |
| `/` | Карточки public/ready/visible видео, превью, автор, длительность, подгрузка |
| `/results?q=` | Поиск по подстроке без учёта регистра, loading/empty/error/retry |
| `/watch/:id` | Плеер, лайк/снятие, комментарии с пагинацией и формой для сессии |
| `GET /api/videos?q=&cursor=&limit=` | Публичная выдача, keyset `(published_at DESC, id DESC)` |
| `GET /api/videos/{id}` | Метаданные просмотра с `likes_count` и `liked_by_me` |
| `PUT/DELETE /api/videos/{id}/like` | Идемпотентное изменение своего лайка |
| `GET/POST /api/videos/{id}/comments` | Чтение с keyset `(created_at ASC, id ASC)`, добавление текста |

Поиск проверен для кириллицы, буквальных `%`, `_`, `!` и обратного слеша.
Доступ к взаимодействиям проверяется через `can_watch`, изменения требуют
Origin, сессию и CSRF. Роли moderator/admin не обходят приватность.

Миграция `694349d098b8` следует за `c970a1085bb1`, добавляет только `likes` и
`comments`: составной PK лайка, FK, CHECK текста и индекс комментариев.
Рабочая БД находится на этой head-ревизии; `alembic check` на тестовой БД не
обнаружил расхождений с metadata. Существующий видеоконвейер не меняется.

## Фактически выполненные проверки

| Проверка | Результат |
| --- | --- |
| `python3 scripts/run_checks.py` | **151 passed**, включая 32 проверки feed/interactions, 8 pagination и существующие video/worker/Range-регрессии |
| `python3 -m unittest discover -s scripts/tests -v` | **7 passed** |
| Ruff: `ruff check app migrations tests` через `run_checks.py` | Успешно |
| Ruff: `ruff format --check app migrations tests` | 71 файл соответствует формату |
| `docker compose --profile checks run --build --rm frontend-checks` | TypeScript typecheck и production build успешны, повторены после CSS-правки |
| `alembic check`, `alembic current` | Схема согласована; рабочая head `694349d098b8` |
| `tests/e2e/social.cjs`, Chromium | Полный реальный сценарий прошёл |
| `tests/e2e/feed_state.cjs`, Chromium | Поиск/пагинация/error/retry, запоздалые ответы, слияние комментариев, 403 и длинный username прошли; повторён после CSS-правки |
| Финальная read-only браузерная проверка | Три страницы на 390/1440, воспроизведение сохранённого ролика, гостевой режим и консоль — успешно |
| `python3 scripts/check_http.py` | Frontend, docs/OpenAPI, readiness с PG/S3/worker и JSON 404 — успешно |
| `docker compose config --quiet`, `git diff --check HEAD` | Успешно |

Первый запуск backend-проверок завершился кодом 143 без итогового результата;
повторный полный запуск завершился успешно за 41,12 секунды. Осталось одно
предупреждение зависимости: Starlette считает использование `httpx` в
TestClient устаревающим. Ошибок тестов нет; зависимости в этой задаче не менялись.

Полный E2E подтвердил регистрацию → загрузку → настоящий FFmpeg → продвижение
`currentTime` → лайк → комментарий → reload. Лайк и комментарий сохранились,
HTML не исполнился. Проверены гостевые запреты, private grant и revoke.
